(()=>{'use strict';const root=document.querySelector('.why-process');if(!root)return;const steps=[{"label":"Първо разговор","title":"Разкажете ни от какво имате нужда.","text":"За нов автомобил, за дома или за семейството — искаме първо да разберем вашия случай. Ще поговорим за бюджета и въпросите ви, преди да разгледаме предложенията.","points":["Можете да попитате и за нещата, които ви изглеждат дребни.","Ще обясним покритията и изключенията на разбираем език."]},{"label":"После сравнение","title":"Нека видим какво стои зад цената.","text":"Ще сравним оферти от различни застрахователи и ще ви покажем съществените разлики. Освен цената ще обсъдим покритията, лимитите и условията, които имат значение за вас.","points":["Ще уточним общата цена и възможностите за плащане.","Решението е ваше. Ние сме тук, за да помогнем с избора."]},{"label":"До вас при щета","title":"Можете да ни потърсите и след това.","text":"При подновяване, щета или въпрос по полицата можете да се обърнете към нашия офис. Ще ви насочим към необходимите документи и следващите стъпки при застрахователя.","points":["Насоки, когато не знаете откъде да започнете.","Съдействие и когато дойде време за подновяване."]}],tabs=[...root.querySelectorAll('[data-step]')],panel=root.querySelector('#process-panel');function activate(i,focus=false){tabs.forEach((b,n)=>{b.setAttribute('aria-selected',String(n===i));b.tabIndex=n===i?0:-1});panel.setAttribute('aria-labelledby',tabs[i].id);panel.querySelector('h3').textContent=steps[i].title;panel.querySelector('p').textContent=steps[i].text;panel.querySelector('ul').replaceChildren(...steps[i].points.map(text=>{const li=document.createElement('li');li.textContent=text;return li}));if(focus)tabs[i].focus()}tabs.forEach((b,i)=>{b.addEventListener('click',()=>activate(i));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();activate(n,true)}})});})();